/**
 * Typed client for the backend. Types come from the API's own schema (schema.ts, generated by
 * `npm run api:types` while the API is running), so the frontend cannot drift from it.
 * All timestamps are UTC strings. `asOf` views the dashboard at a past moment.
 */
import { ApiError, NOT_ANSWERING } from "./errors";
import { applyFault } from "./fault";
import type { components } from "./schema";

type Schemas = components["schemas"];

export type Meta = Schemas["Meta"];
export type Forecast = Schemas["Forecast"];
export type ForecastStep = Schemas["ForecastStep"];
export type Driver = Schemas["Driver"];
export type Changes = Schemas["Changes"];
export type ChangePoint = Schemas["ChangePoint"];
export type Actuals = Schemas["Actuals"];
export type ActualPoint = Schemas["ActualPoint"];
export type Alerts = Schemas["Alerts"];
export type Alert = Schemas["Alert"];
export type AlertKind = Alert["kind"];
export type AlertHistory = Schemas["AlertHistory"];
export type Situation = Schemas["Situation"];
export type SituationHour = Schemas["SituationHour"];
export type Performance = Schemas["Performance"];
export type Scores = Schemas["Scores"];
export type ScoreSet = Schemas["ScoreSet"];
export type HorizonScores = Schemas["HorizonScores"];
export type Hindsight = Schemas["Hindsight"];
export type HindsightPoint = Schemas["HindsightPoint"];
export type Notes = Schemas["Notes"];
export type Note = Schemas["Note"];
export type UmmFeed = Schemas["UmmFeed"];
export type UmmMessage = Schemas["UmmMessage"];

/**
 * /api/fuel/snapshot returns a plain dict (backend/fuel/service.py build_snapshot), so it has no generated
 * schema. Only the fields the CHP screen reads. Prices EUR/MWh, null where no price is known.
 */
export type FuelSnapshot = {
  label: string;
  eua: { eur_t: number; as_of: string | null; source: string };
  fuels: Record<string, { eur_mwh: number | null; period: string | null; source: string; eur_mwh_incl_co2: number | null }>;
  heat: { heat_only_boiler_eur_mwh: number | null; e_boiler_cheaper_below_spot: number | null };
  chp: {
    unit: string;
    by_fuel: { fuel: string; fuel_eur_mwh_incl_co2: number | null; power_cost_after_heat_credit: number | null }[];
  };
  /** The electric boiler's efficiency and its grid fee, tax and other costs per MWh of electricity. */
  assumptions: { EB: { eta: number; adders_eur_mwh: number } };
  errors: Record<string, string>;
};

type Query = Record<string, string | number | undefined>;

async function request<T>(path: string, query: Query): Promise<T> {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value !== undefined) params.set(key, String(value));
  }
  const text = params.toString();
  let response: Response;
  try {
    response = await fetch(text ? `${path}?${text}` : path);
  } catch {
    throw new ApiError(NOT_ANSWERING, null);
  }
  if (!response.ok) {
    const body = (await response.json().catch(() => null)) as { detail?: unknown } | null;
    throw new ApiError(typeof body?.detail === "string" ? body.detail : NOT_ANSWERING, response.status);
  }
  return (await response.json()) as T;
}

function get<T>(path: string, query: Query = {}): Promise<T> {
  return applyFault(() => request<T>(path, query));
}

export const api = {
  meta: () => get<Meta>("/api/meta"),
  forecast: (asOf?: string) => get<Forecast>("/api/forecast", { as_of: asOf }),
  changes: (asOf?: string) => get<Changes>("/api/changes", { as_of: asOf }),
  alerts: (asOf?: string) => get<Alerts>("/api/alerts", { as_of: asOf }),
  alertHistory: (asOf?: string) => get<AlertHistory>("/api/alerts/history", { as_of: asOf }),
  actuals: (asOf?: string, from?: string, to?: string) => get<Actuals>("/api/actuals", { as_of: asOf, from, to }),
  performance: (asOf?: string, from?: string, to?: string) => get<Performance>("/api/performance", { as_of: asOf, from, to }),
  hindsight: (asOf: string | undefined, from: string, to: string, leadHours: number) =>
    get<Hindsight>("/api/hindsight", { as_of: asOf, from, to, lead_hours: leadHours }),
  notes: (asOf: string | undefined, persona: "trader" | "operator") => get<Notes>("/api/notes", { as_of: asOf, persona }),
  umm: (asOf: string | undefined, hours: number, minMw: number) => get<UmmFeed>("/api/umm", { as_of: asOf, hours, min_mw: minMw }),
  /** Never pass spot here: the query string lands in the API's access log (AGENTS.md rule 6). */
  fuel: () => get<FuelSnapshot>("/api/fuel/snapshot"),
};

export { ApiError };
